	const clean = req.path.replace(/^\/api/, '').replace(/^\/|\/$/g, '');
	const parts = clean.split('/').slice(0, 3);
	parts.forEach((p, index) => {
		try {
			p = slugify(decodeURIComponent(p));
		} catch (err) {
			winston.error(`Error decoding URI: ${p}`);
			winston.error(err.stack);
